-- virgin-active-steenberg-steenberg (researched)
UPDATE businesses SET description = 'Virgin Active Steenberg is a gym with a heated lap pool for lane swimming and squad training, plus a smaller heated leisure pool for aqua classes, swimming lessons or play. The club has a sauna and steam room, functional training equipment such as kettlebells, Bulgarian bags and slam balls, a Ride studio for indoor cycling, and a Mind Body studio for yoga and Pilates.

Other facilities include a rowing area, Wattbikes with app integration, an access-controlled kids'' space called Club V for children from six weeks to 13 years, an accessible changeroom, treatment rooms for massage therapists and physiotherapists, and free WiFi. Membership pricing varies by age and contract length, and the club offers a free gym plan trial and a refer-a-friend scheme.

It suits families and serious trainers alike who want a full-service gym with pools, classes and childcare in Steenberg.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.virginactive.co.za/gyms/steenberg'), description_enriched_at = datetime('now') WHERE slug = 'virgin-active-steenberg-steenberg' AND description = 'Virgin Active Steenberg is a health club in Westlake Business Park offering two heated swimming pools with aqua fitness classes, a supervised kids'' club, sauna and steam room facilities, personal training, and free underground parking.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
